<script setup lang="ts">import { computed, onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { api } from '../lib/api'; const router=useRouter(),rows=ref<any[]>([]), error=ref(''),mode=ref<'damaged'|'unlocated'>('damaged'); const visible=computed(()=>rows.value.filter((row:any)=>mode.value==='damaged'?Number(row.damaged_qty)>0:Number(row.pending_qty)>0)); onMounted(async()=>{try{rows.value=(await api('inventory',{needs_attention:1,page_length:25})).results||[];if(!rows.value.some((row:any)=>Number(row.damaged_qty)>0))mode.value='unlocated'}catch(e:any){error.value=e.message}}); function begin(row:any,kind:string){sessionStorage.setItem(`ti-seed:${kind}`,JSON.stringify({items:[row.item_code]}));void router.push(`/new/${kind}`)}</script>
<template><section class="app-shell wide-shell"><header><RouterLink to="/">‹ 库存</RouterLink><h1>待处理</h1></header><p>仅显示损坏或未定位的实际库存。</p><nav class="inventory-modes" aria-label="待处理类型"><button :class="{active:mode==='damaged'}" @click="mode='damaged'">损坏</button><button :class="{active:mode==='unlocated'}" @click="mode='unlocated'">未定位</button></nav><p v-if="error" class="error">{{error}}</p><article v-for="row in visible" :key="row.item_code" class="selection-row"><RouterLink :to="`/item/${encodeURIComponent(row.item_code)}`"><b>{{row.item_name}}</b><small>损坏 {{row.damaged_qty}} · 未定位 {{row.pending_qty}} {{row.stock_uom}}</small></RouterLink><div class="detail-actions"><button v-if="row.pending_qty" @click="begin(row,'Transfer')">分配到位置</button><button v-if="row.damaged_qty" @click="begin(row,'Repair')">修复归库</button><button v-if="row.damaged_qty" @click="begin(row,'Disposal')">正式报废</button></div></article><p v-if="!visible.length&&!error" class="empty-state">暂无{{mode==='damaged'?'损坏':'未定位'}}库存</p></section></template>
